-- Diagnóstico (25-11): artistas ⭐ con conciertos futuros en recintos grandes (solo metadatos)
SELECT COUNT(DISTINCT s.artist_id) AS artistas FROM show s JOIN follow f ON f.artist_id = s.artist_id JOIN venue_info v ON v.tm_venue_id = json_extract(s.snapshot_json, '$.venue.tmId') WHERE f.tier = 1 AND s.local_date >= '2026-11-25' AND v.capacity >= 15000;
SELECT a.name, COUNT(*) AS fechas, MAX(v.capacity) AS aforo_max, COUNT(DISTINCT s.country) AS paises FROM show s JOIN artist a ON a.id = s.artist_id JOIN follow f ON f.artist_id = s.artist_id JOIN venue_info v ON v.tm_venue_id = json_extract(s.snapshot_json, '$.venue.tmId') WHERE f.tier = 1 AND s.local_date >= '2026-11-25' AND v.capacity >= 8000 AND s.is_package = 0 GROUP BY a.id HAVING MAX(v.capacity) >= 15000 OR COUNT(*) >= 3 ORDER BY fechas DESC LIMIT 60;
SELECT a.name, f.tier, (SELECT COUNT(*) FROM show s WHERE s.artist_id = a.id AND s.local_date >= '2026-11-25') AS fechas FROM artist a LEFT JOIN follow f ON f.artist_id = a.id WHERE lower(a.name) LIKE 'charli%';
